import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The claims people make on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** The amount is a number with up to two decimals, 0.00 or more; no date means the sheet's today. */
    public record ClaimForm(
            @NotNull @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 1000) String note) {}

    /** The amount is shown with two decimals; a claim has no number until it is opened, and no fixed due
     * until it is settled; it shows who opened it, if anyone did, and whether it is bound to the figure it had
     * at its person's last statement (none when that was n/a). */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            Integer number, String due, String openedBy, boolean stated, String statedDue) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2).toPlainString(), claim.getDate(), claim.getNote(), claim.getStatus(),
                    claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().setScale(2).toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().setScale(2).toPlainString() : null);
        }
    }

    private final ClaimService service;

    public ClaimController(ClaimService service) {
        this.service = service;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    public ClaimView add(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long personId, @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.add(user, sheetId, personId, new BigDecimal(form.amount()), form.date(), form.note()));
    }

    @PutMapping("/claims/{id}")
    public ClaimView update(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.update(user, sheetId, id, new BigDecimal(form.amount()), form.date(), form.note()));
    }

    @PostMapping("/claims/{id}/open")
    public ClaimView open(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.VOID));
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementService.Summary;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The people kept on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            Long version) {}

    /** A person shows how many statements were taken for them and the last one's due-total (n/a when it was)
     * and date; none of those before the first. */
    public record PersonView(Long id, String name, String grade, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held) {

        public static PersonView of(Person person, Map<Long, Summary> statements) {
            Summary summary = statements.get(person.getId());
            Statement last = summary != null ? summary.last() : null;
            return new PersonView(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                    summary != null ? summary.count() : 0,
                    last == null ? null : last.getDueTotal() != null ? last.getDueTotal().toPlainString() : "n/a",
                    last != null ? last.getTakenOn() : null, person.getRetiredFrom(), person.isHeld());
        }
    }

    private final PersonService service;
    private final StatementService statements;

    public PersonController(PersonService service, StatementService statements) {
        this.service = service;
        this.statements = statements;
    }

    @GetMapping
    public List<PersonView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        List<Person> people = service.list(sheetId);
        Map<Long, Summary> taken = statements.summaries(sheetId);
        return people.stream().map(p -> PersonView.of(p, taken)).toList();
    }

    @PostMapping
    public PersonView add(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody PersonForm form) {
        return PersonView.of(service.add(user, sheetId, form.name(), form.grade()), statements.summaries(sheetId));
    }

    @PutMapping("/{id}")
    public PersonView update(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody PersonForm form) {
        return PersonView.of(service.update(user, sheetId, id, form.name(), form.grade(), form.version()),
                statements.summaries(sheetId));
    }

    public record RetireForm(LocalDate from) {}

    /** Retire the person from a date, the sheet's today when none is given. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @RequestBody RetireForm form) {
        return PersonView.of(service.retire(user, sheetId, id, form.from()), statements.summaries(sheetId));
    }

    /** Put the person on hold, or take them off it when held. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return PersonView.of(service.toggleHold(user, sheetId, id), statements.summaries(sheetId));
    }

    /** Take a statement for the person. */
    @PostMapping("/{id}/statement")
    public PersonView statement(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return PersonView.of(statements.take(user, sheetId, id), statements.summaries(sheetId));
    }
}

